#!/usr/bin/env bash
# install-lancedb-opencode-pro-patches.sh
#
# Self-contained installer for a patched build of the `lancedb-opencode-pro`
# OpenCode memory plugin. Fetches the pristine 0.8.2 package from the public
# npm registry into OpenCode's plugin cache, overlays 9 bug/behavior patches
# (embedded below, base64), writes a tuned config sidecar file, and pins the
# plugin version in opencode.jsonc. Idempotent — safe to re-run.
#
# Usage:
#   bash install-lancedb-opencode-pro-patches.sh
#
# Requires: node + npm on PATH, internet access to registry.npmjs.org.
# Works regardless of your login shell (zsh/bash) since you invoke it via
# `bash ...` explicitly.
#
# ---------------------------------------------------------------------------
# What gets patched, and why (each is a real bug fix unless noted):
#
# 1. extract.js (marker ALL_CAPTURE_SIGNALS) — auto-capture keyword gate was
#    too narrow (9 keywords, positive-signals only). Widened to ~40 keywords
#    and now also captures decision/fact/preference signals. Also exports
#    GLOBAL_KEYWORDS (entity lexicon, incl. GRAPH_STORE_PHASE2 terms like
#    opencode/systemd/plugin/graph) used by graph.js.
#
# 2. index.js (marker persistSuccessPatterns) — plugin listened for
#    nonexistent events session.start/session.end; real OpenCode >=1.x
#    events are session.created/session.deleted with sessionID at
#    properties.info.id (not properties.sessionID). This silently broke ALL
#    episodic task tracking. Also fixes scope resolution to use the actual
#    per-session directory (not the static plugin-init worktree) in both the
#    capture path and the recall hook — without this, captured memories can
#    become permanently invisible to recall on long-lived multi-project
#    server processes. Also wires up the previously dead-code episodic
#    learning subsystem (tool.execute.after hook logs real bash
#    commands/validation outcomes into task episodes) and fixes success-
#    pattern persistence (was computed then discarded every turn; now
#    persisted once per successful task completion).
#
# 3. tools/memory.js, tools/episodic.js, tools/feedback.js (marker
#    "context.directory || context.worktree" — tools/memory.js now marker
#    MEMORY_LIFECYCLE_TOOLS) — all memory/episodic/feedback tools derived
#    scope from context.worktree alone; prefers the more accurate per-session
#    context.directory now, consistent with fix #2. tools/memory.js also
#    gained memory_export / memory_import / memory_summarize (0.9, see #7).
#
# 4. scope.js (marker SCOPING_TOGGLE) — runtime scope-mode switch. The plugin
#    config key `scoping` ("global" default | "project", env override
#    LANCEDB_OPENCODE_PRO_SCOPING) selects between the single-user global
#    mode (every scope collapses to "global"; all memories searchable from
#    any session/directory) and upstream per-project scoping (partitioned by
#    git remote URL / local directory hash, global scope still searched when
#    includeGlobalScope is enabled). No longer an install-time preference —
#    always applied, because it also carries the scope-filter dedup fix
#    ([...new Set] collapse, needed to avoid doubled search results).
#
# 5. store.js (marker ATOMIC_UPDATE_MEMORY_USAGE + MEMORY_LIFECYCLE_TOOLS) —
#    updateMemoryUsage()
#    (bumps recallCount/lastRecalled on every recall, i.e. every chat turn)
#    used delete()+add() to simulate an update: two non-atomic ops with no
#    compaction ever called, which can leave duplicate physical rows for the
#    same memory id under real recall traffic. Now uses a single atomic
#    table.update() call instead. 0.9 additions (MEMORY_LIFECYCLE_TOOLS):
#    exportAllRecords() (full-fidelity backup incl. disabled/merged/digested
#    rows), findRawRecordsByIds(), markDigested() (status "digested" +
#    digestedInto metadata, atomic per-row update), extractiveDigest() (pure,
#    offline sentence-scoring summarizer), and digested rows are now excluded
#    from recall (readByScopes / findRecordsByIds).
#
# 6. graph.js (NEW FILE, marker GRAPH_STORE_POLISH) — offline entity graph.
#    Phase 1: pure-heuristic entity extraction (file paths, config keys,
#    camelCase/snake_case identifiers, infra lexicon — no LLM), stored in a
#    sqlite DB (~/.opencode/memory/graph.db) with entities + co-occurrence
#    edges. Recall gets a multiplicative graphBoost when the query shares
#    extracted entities with a memory. Global-only by design (single-user).
#    Phase 2: typed-relation edges — sentence-level verb-pattern heuristics
#    ("X uses Y", "X depends on Z", "X runs on Y", "X configured in Y",
#    connects_to/part_of/managed_by/manages/imports/writes_to/reads_from)
#    emit directional edges in addition to co_occurs, only when BOTH
#    endpoints are real extracted entities; a conjunctive-continuation rule
#    handles "A uses B and runs on C". Config: graph.typedEdges (default
#    true, env LANCEDB_OPENCODE_PRO_GRAPH_TYPED_EDGES). stats() now reports
#    a per-relation breakdown. Uses bun:sqlite when running under the
#    Bun-based opencode binary, falling back to node:sqlite; graph degrades
#    gracefully (disabled) if neither driver is available.
#    Phase 2b: graph-expansion recall — bounded BFS from the query's
#    extracted entities (up to graph.maxHops, preferring typed relations),
#    collecting memories reachable via memory_entities that did NOT
#    text/vector-match, merged into results with a graph-origin score
#    ([graph-bfs: N hops] marker). Config: graph.expansionEnabled / maxHops
#    / expansionLimit / expansionLambda (env LANCEDB_OPENCODE_PRO_GRAPH_*).
#    Phase polish (0.9): boostResults strength smoothed (1-entity match
#    0.75 instead of 0.5; >=2 entities capped at 1.0) and typed-edge
#    preference in expandRecall raised 1.3x -> 1.5x.
#
# 7. config.js (marker resolveGraphConfig + MEMORY_LIFECYCLE_TOOLS) — resolves the new "graph"
#    config section (enabled/dbPath/boostLambda/maxEntitiesPerMemory/
#    maxEdgeProvenance/typedEdges/expansionEnabled/maxHops/expansionLimit/
#    expansionLambda) with env overrides, merged like dedup/retrieval.
#    Also store.js (marker GRAPH_STORE_PHASE1) — MemoryStore gains
#    attachGraph() + provenance cleanup: memories deleted/soft-deleted/
#    pruned/cleared are removed from the graph, and dedup merges repoint
#    graph mappings from the merged-away row to the survivor. store.js also
#    gains findRecordsByIds() (marker GRAPH_STORE_PHASE2B) so graph
#    expansion candidates can be fetched without a full-scope read.
#    0.9: config.js adds the "summarize" section (enabled/minAgeDays/
#    minGroupSize/targetChars/replace, env LANCEDB_OPENCODE_PRO_SUMMARIZE_*)
#    for the offline digest summarizer; tools/memory.js gains
#    memory_export / memory_import / memory_summarize (MEMORY_LIFECYCLE_TOOLS).
# All patches use marker-string checks, so re-running this script (e.g.
# after an opencode/plugin cache wipe) is safe and will not double-patch.
# ---------------------------------------------------------------------------

set -euo pipefail

PKG_VERSION="0.8.2"
PKG_NAME="lancedb-opencode-pro"
CACHE_DIR="$HOME/.cache/opencode/packages/${PKG_NAME}@${PKG_VERSION}"
DIST_DIR="$CACHE_DIR/node_modules/${PKG_NAME}/dist"
CONFIG_FILE="$HOME/.config/opencode/lancedb-opencode-pro.json"
OPENCODE_JSONC="$HOME/.config/opencode/opencode.jsonc"
STAGING_DIR=$(mktemp -d)
trap 'rm -rf "$STAGING_DIR"' EXIT

echo "== lancedb-opencode-pro patched installer =="
echo

# ---------------------------------------------------------------------------
# Step 0: sanity checks
# ---------------------------------------------------------------------------
if ! command -v node >/dev/null 2>&1; then
  echo "ERROR: node is required but not found on PATH." >&2
  exit 1
fi
if ! command -v npm >/dev/null 2>&1; then
  echo "ERROR: npm is required but not found on PATH." >&2
  exit 1
fi

# ---------------------------------------------------------------------------
# Step 1: fetch pristine package into OpenCode's plugin cache layout
# ---------------------------------------------------------------------------
if [ -d "$DIST_DIR" ]; then
  echo "Step 1/5: $PKG_NAME@$PKG_VERSION already present in cache, skipping npm install."
else
  echo "Step 1/5: installing $PKG_NAME@$PKG_VERSION into OpenCode's plugin cache..."
  mkdir -p "$CACHE_DIR"
  cat > "$CACHE_DIR/package.json" <<PKGJSON
{
  "dependencies": {
    "$PKG_NAME": "$PKG_VERSION"
  }
}
PKGJSON
  (cd "$CACHE_DIR" && npm install --no-audit --no-fund --silent)
  if [ ! -d "$DIST_DIR" ]; then
    echo "ERROR: npm install completed but $DIST_DIR still doesn't exist. Aborting." >&2
    exit 1
  fi
  echo "  installed OK."
fi
echo

# ---------------------------------------------------------------------------
# Step 2: extract embedded patch files to staging dir (base64 blobs below)
# ---------------------------------------------------------------------------
echo "Step 2/5: extracting embedded patches..."
mkdir -p "$STAGING_DIR/$(dirname 'extract.js')"
base64 -d > "$STAGING_DIR/extract.js" <<'B64_extract_js_EOF'

B64_extract_js_EOF

mkdir -p "$STAGING_DIR/$(dirname 'index.js')"
base64 -d > "$STAGING_DIR/index.js" <<'B64_index_js_EOF'

B64_index_js_EOF

mkdir -p "$STAGING_DIR/$(dirname 'tools/memory.js')"
base64 -d > "$STAGING_DIR/tools/memory.js" <<'B64_tools_memory_js_EOF'

B64_tools_memory_js_EOF

mkdir -p "$STAGING_DIR/$(dirname 'tools/episodic.js')"
base64 -d > "$STAGING_DIR/tools/episodic.js" <<'B64_tools_episodic_js_EOF'

B64_tools_episodic_js_EOF

mkdir -p "$STAGING_DIR/$(dirname 'tools/feedback.js')"
base64 -d > "$STAGING_DIR/tools/feedback.js" <<'B64_tools_feedback_js_EOF'

B64_tools_feedback_js_EOF

mkdir -p "$STAGING_DIR/$(dirname 'scope.js')"
base64 -d > "$STAGING_DIR/scope.js" <<'B64_scope_js_EOF'

B64_scope_js_EOF

mkdir -p "$STAGING_DIR/$(dirname 'store.js')"
base64 -d > "$STAGING_DIR/store.js" <<'B64_store_js_EOF'

B64_store_js_EOF

mkdir -p "$STAGING_DIR/$(dirname 'config.js')"
base64 -d > "$STAGING_DIR/config.js" <<'B64_config_js_EOF'

B64_config_js_EOF

mkdir -p "$STAGING_DIR/$(dirname 'graph.js')"
base64 -d > "$STAGING_DIR/graph.js" <<'B64_graph_js_EOF'
