echo "  extracted 9 patch files."
echo

# ---------------------------------------------------------------------------
# Step 3: apply patches (idempotent, marker-checked)
# ---------------------------------------------------------------------------
echo "Step 3/5: applying patches..."

apply_patch() {
  local rel="$1" marker="$2"
  local src="$STAGING_DIR/$rel"
  local target="$DIST_DIR/$rel"

  if [ ! -f "$target" ]; then
    echo "  WARN: $target not found, skipping." >&2
    return
  fi
  if grep -qF "$marker" "$target"; then
    echo "  already patched: $rel"
    return
  fi
  cp "$target" "$target.orig.bak" 2>/dev/null || true
  cp "$src" "$target"
  echo "  patched: $rel"
}

apply_patch "extract.js" "ALL_CAPTURE_SIGNALS"
apply_patch "index.js" "persistSuccessPatterns"
apply_patch "tools/memory.js" "MEMORY_LIFECYCLE_TOOLS"
apply_patch "tools/episodic.js" "context.directory || context.worktree"
apply_patch "tools/feedback.js" "context.directory || context.worktree"
apply_patch "store.js" "MEMORY_LIFECYCLE_TOOLS"
apply_patch "config.js" "MEMORY_LIFECYCLE_TOOLS"
if [ ! -f "$DIST_DIR/graph.js" ] || ! grep -qF "GRAPH_STORE_POLISH" "$DIST_DIR/graph.js"; then
  cp "$STAGING_DIR/graph.js" "$DIST_DIR/graph.js"
  echo "  installed: graph.js (new file)"
else
  echo "  already patched: graph.js"
fi

echo
echo "  The remaining patch (scope.js) is ALWAYS applied: it carries both"
echo "  the scope-filter dedup fix and the runtime 'scoping' config toggle"
echo "  (\"global\" default | \"project\", env: LANCEDB_OPENCODE_PRO_SCOPING)."
echo "  See the installed config file: scoping key."
apply_patch "scope.js" "SCOPING_TOGGLE"
echo

# ---------------------------------------------------------------------------
# Step 4: write config sidecar file (tuned defaults; prompts for secrets)
# ---------------------------------------------------------------------------
echo "Step 4/5: config file ($CONFIG_FILE)..."

write_config() {
  local api_key="$1" base_url="$2"
  mkdir -p "$(dirname "$CONFIG_FILE")"
  cat > "$CONFIG_FILE" <<CONFIGEOF
{
  "provider": "lancedb-opencode-pro",
  "dbPath": "~/.opencode/memory/lancedb",
  "embedding": {
    "provider": "openai",
    "model": "titan-embed-text-v2",
    "baseUrl": "$base_url",
    "apiKey": "$api_key",
    "timeoutMs": 6000,
    "retry": {
      "enabled": true,
      "maxAttempts": 3,
      "initialDelayMs": 1000,
      "backoffMultiplier": 2
    }
  },
  "retrieval": {
    "mode": "hybrid",
    "vectorWeight": 0.7,
    "bm25Weight": 0.3,
    "minScore": 0.2,
    "rrfK": 60,
    "recencyBoost": true,
    "recencyHalfLifeHours": 504,
    "importanceWeight": 0.4,
    "feedbackWeight": 0.3
  },
  "injection": {
    "mode": "fixed",
    "maxMemories": 3,
    "minMemories": 1,
    "budgetTokens": 4096,
    "maxCharsPerMemory": 3000,
    "summarization": "auto",
    "summaryTargetChars": 300,
    "scoreDropTolerance": 0.15,
    "injectionFloor": 0.2,
    "codeSummarization": {
      "enabled": true,
      "pureCodeThreshold": 500,
      "maxCodeLines": 15,
      "codeTruncationMode": "smart",
      "preserveComments": true,
      "preserveImports": false
    }
  },
  "dedup": {
    "enabled": true,
    "writeThreshold": 0.88,
    "consolidateThreshold": 0.95,
    "candidateLimit": 50
  },
  "includeGlobalScope": true,
  "scoping": "global",
  "globalDetectionThreshold": 2,
  "globalDiscountFactor": 0.7,
  "unusedDaysThreshold": 30,
  "minCaptureChars": 80,
  "maxEntriesPerScope": 3000,
  "graph": {
    "enabled": true,
    "dbPath": "~/.opencode/memory/graph.db",
    "boostLambda": 0.3,
    "maxEntitiesPerMemory": 20,
    "maxEdgeProvenance": 20,
    "typedEdges": true,
    "expansionEnabled": true,
    "maxHops": 2,
    "expansionLimit": 5,
    "expansionLambda": 0.3
  },
  "retention": {
    "effectivenessEventsDays": 90,
    "memory": {
      "enabled": true,
      "unusedDays": 60,
      "minAgeDays": 180,
      "minGroupSize": 2,
      "targetChars": 500,
      "minImportance": 0.3,
      "protectedCategories": ["digest"]
    }
  },
  "summarize": {
    "enabled": true,
    "minAgeDays": 30,
    "minGroupSize": 3,
    "targetChars": 500,
    "replace": false
  }
}
CONFIGEOF
}

if [ -f "$CONFIG_FILE" ]; then
  echo "  $CONFIG_FILE already exists."
  OVERWRITE="n"
  if [ -t 0 ]; then
    read -r -p "  Overwrite with the tuned config (backs up existing first)? [y/N] " ans || true
    case "$ans" in
      [yY]|[yY][eE][sS]) OVERWRITE="y" ;;
    esac
  fi
  if [ "$OVERWRITE" = "y" ]; then
    cp "$CONFIG_FILE" "$CONFIG_FILE.bak.$(date +%s)"
    echo "  backed up existing config."
  else
    echo "  leaving existing config untouched, skipping."
    OVERWRITE="skip"
  fi
else
  OVERWRITE="y"
fi

if [ "$OVERWRITE" = "y" ]; then
  DEFAULT_BASE_URL="https://dev-aigw-atlas.verizon.com:4000/v1"
  API_KEY=""
  BASE_URL=""
  if [ -n "${LANCEDB_EMBED_API_KEY:-}" ]; then
    API_KEY="$LANCEDB_EMBED_API_KEY"
    echo "  using LANCEDB_EMBED_API_KEY from environment."
  elif [ -t 0 ]; then
    read -r -s -p "  Enter embedding API key (input hidden): " API_KEY
    echo
  fi
  if [ -n "${LANCEDB_EMBED_BASE_URL:-}" ]; then
    BASE_URL="$LANCEDB_EMBED_BASE_URL"
  elif [ -t 0 ]; then
    read -r -p "  Embedding gateway base URL [$DEFAULT_BASE_URL]: " BASE_URL
  fi
  BASE_URL="${BASE_URL:-$DEFAULT_BASE_URL}"
  if [ -z "$API_KEY" ]; then
    API_KEY="REPLACE_ME"
    echo "  WARNING: no API key provided — wrote placeholder \"REPLACE_ME\"."
    echo "  Edit $CONFIG_FILE and set embedding.apiKey before using the plugin."
  fi
  write_config "$API_KEY" "$BASE_URL"
  echo "  wrote $CONFIG_FILE"
fi
echo

# ---------------------------------------------------------------------------
# Step 5: pin plugin version in opencode.jsonc
# ---------------------------------------------------------------------------
echo "Step 5/5: checking $OPENCODE_JSONC plugin pin..."

PIN_LINE="\"$PKG_NAME@$PKG_VERSION\""

if [ ! -f "$OPENCODE_JSONC" ]; then
  echo "  $OPENCODE_JSONC does not exist yet — creating a minimal one."
  mkdir -p "$(dirname "$OPENCODE_JSONC")"
  cat > "$OPENCODE_JSONC" <<JSONCEOF
{
  "\$schema": "https://opencode.ai/config.json",
  "plugin": [
    $PIN_LINE
  ]
}
JSONCEOF
  echo "  created $OPENCODE_JSONC with the plugin pinned."
elif grep -qF "$PKG_NAME@" "$OPENCODE_JSONC"; then
  if grep -qF "$PKG_NAME@$PKG_VERSION" "$OPENCODE_JSONC"; then
    echo "  already pinned to $PKG_NAME@$PKG_VERSION."
  else
    echo "  NOTE: found a different $PKG_NAME version pinned in $OPENCODE_JSONC."
    echo "  Not auto-changing it — update it manually to \"$PKG_NAME@$PKG_VERSION\" if you want this exact patched build."
  fi
elif grep -qF '"plugin"' "$OPENCODE_JSONC"; then
  BACKUP_FILE="$OPENCODE_JSONC.bak.$(date +%s)"
  cp "$OPENCODE_JSONC" "$BACKUP_FILE"
  # Insert right after the first "plugin": [ line.
  awk -v pin="$PIN_LINE" '
    { print }
    /"plugin"[[:space:]]*:[[:space:]]*\[/ && !done {
      print "    " pin ","
      done = 1
    }
  ' "$BACKUP_FILE" > "$OPENCODE_JSONC.tmp" 2>/dev/null || true
  if [ -s "$OPENCODE_JSONC.tmp" ]; then
    mv "$OPENCODE_JSONC.tmp" "$OPENCODE_JSONC"
    echo "  inserted plugin pin into existing \"plugin\" array (backup saved)."
    echo "  Please double-check $OPENCODE_JSONC is still valid JSONC (a backup was saved alongside it)."
  else
    echo "  WARNING: could not safely auto-edit $OPENCODE_JSONC (unexpected format)."
    echo "  Please add this line inside your \"plugin\" array manually:"
    echo "      $PIN_LINE"
  fi
else
  cp "$OPENCODE_JSONC" "$OPENCODE_JSONC.bak.$(date +%s)"
  awk -v pin="$PIN_LINE" '
    NR==1 && /\{/ {
      print
      print "  \"plugin\": [" pin "],"
      next
    }
    { print }
  ' "$OPENCODE_JSONC" > "$OPENCODE_JSONC.tmp"
  mv "$OPENCODE_JSONC.tmp" "$OPENCODE_JSONC"
  echo "  added a new \"plugin\" array with the pin (backup saved)."
  echo "  Please double-check $OPENCODE_JSONC is still valid JSONC."
fi

echo
echo "== Done =="
echo "Restart OpenCode (fully quit and reopen, not just a new session on the"
echo "same server process) for the patched plugin to load. Then verify with"
echo "the memory_stats tool inside a session — it should return without error."
